1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net/sched: cls_flow: fix NULL pointer dereference on shared
 blocks

flow_change() calls tcf_block_q() and dereferences q->handle to derive
a default baseclass.  Shared blocks leave block->q NULL, causing a NULL
deref when a flow filter without a fully qualified baseclass is created
on a shared block.

Check tcf_block_shared() before accessing block->q and return -EINVAL
for shared blocks.  This avoids the null-deref shown below:

=======================================================================
KASAN: null-ptr-deref in range [0x0000000000000038-0x000000000000003f]
RIP: 0010:flow_change (net/sched/cls_flow.c:508)
Call Trace:
 tc_new_tfilter (net/sched/cls_api.c:2432)
 rtnetlink_rcv_msg (net/core/rtnetlink.c:6980)
 [...]
=======================================================================

Fixes: 1abf272022cf ("net: sched: tcindex, fw, flow: use tcf_block_q helper to get struct Qdisc")
Reported-by: Weiming Shi <bestswngs@gmail.com>
Signed-off-by: Xiang Mei <xmei5@asu.edu>
Acked-by: Jamal Hadi Salim <jhs@mojatatu.com>
Link: https://patch.msgid.link/20260331050217.504278-2-xmei5@asu.edu
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
In flow_change(), when a flow filter is created on a shared block (where block->q is NULL) without a fully qualified baseclass, the code calls tcf_block_q() to get the Qdisc and then dereferences q->handle. Since q is NULL for shared blocks, this results in a NULL pointer dereference.

Here is the patch:

 static int flow_change(struct net *net, struct sk_buff *in_skb,
 		       struct tcf_proto *tp, unsigned long base,
 		       u32 handle, struct nlattr **tca,
 		       void **arg, u32 flags,
 		       struct netlink_ext_ack *extack)
 {
 	struct flow_head *head = rtnl_dereference(tp->root);
 	struct flow_filter *fold, *fnew;
 	struct nlattr *opt = tca[TCA_OPTIONS];
 	struct nlattr *tb[TCA_FLOW_MAX + 1];
 	unsigned int nkeys = 0;
 	unsigned int perturb_period = 0;
 	u32 baseclass = 0;
 	u32 keymask = 0;
 	u32 mode;
 	int err;

 	if (opt == NULL)
 		return -EINVAL;

 	err = nla_parse_nested_deprecated(tb, TCA_FLOW_MAX, opt, flow_policy,
 					  NULL);
 	if (err < 0)
 		return err;

 	if (tb[TCA_FLOW_BASECLASS]) {
 		baseclass = nla_get_u32(tb[TCA_FLOW_BASECLASS]);
 		if (TC_H_MIN(baseclass) == 0)
 			return -EINVAL;
 	}

 	if (tb[TCA_FLOW_KEYS]) {
 		keymask = nla_get_u32(tb[TCA_FLOW_KEYS]);

 		nkeys = hweight32(keymask);
 		if (nkeys == 0)
 			return -EINVAL;

 		if (fls(keymask) - 1 > FLOW_KEY_MAX)
 			return -EOPNOTSUPP;

 		if ((keymask & (FLOW_KEY_SKUID|FLOW_KEY_SKGID)) &&
 		    sk_user_ns(NETLINK_CB(in_skb).sk) != &init_user_ns)
 			return -EOPNOTSUPP;
 	}

 	fnew = kzalloc_obj(*fnew);
 	if (!fnew)
 		return -ENOBUFS;

 	err = tcf_em_tree_validate(tp, tb[TCA_FLOW_EMATCHES], &fnew->ematches);
 	if (err < 0)
 		goto err1;

 	err = tcf_exts_init(&fnew->exts, net, TCA_FLOW_ACT, TCA_FLOW_POLICE);
 	if (err < 0)
 		goto err2;

 	err = tcf_exts_validate(net, tp, tb, tca[TCA_RATE], &fnew->exts, flags,
 				extack);
 	if (err < 0)
 		goto err2;

 	fold = *arg;
 	if (fold) {
 		err = -EINVAL;
 		if (fold->handle != handle && handle)
 			goto err2;

 		/* Copy fold into fnew */
 		fnew->tp = fold->tp;
 		fnew->handle = fold->handle;
 		fnew->nkeys = fold->nkeys;
 		fnew->keymask = fold->keymask;
 		fnew->mode = fold->mode;
 		fnew->mask = fold->mask;
 		fnew->xor = fold->xor;
 		fnew->rshift = fold->rshift;
 		fnew->addend = fold->addend;
 		fnew->divisor = fold->divisor;
 		fnew->baseclass = fold->baseclass;
 		fnew->hashrnd = fold->hashrnd;

 		mode = fold->mode;
 		if (tb[TCA_FLOW_MODE])
 			mode = nla_get_u32(tb[TCA_FLOW_MODE]);
 		if (mode != FLOW_MODE_HASH && nkeys > 1)
 			goto err2;

 		if (mode == FLOW_MODE_HASH)
 			perturb_period = fold->perturb_period;
 		if (tb[TCA_FLOW_PERTURB]) {
 			if (mode != FLOW_MODE_HASH)
 				goto err2;
 			perturb_period = nla_get_u32(tb[TCA_FLOW_PERTURB]) * HZ;
 		}
 	} else {
 		err = -EINVAL;
 		if (!handle)
 			goto err2;
 		if (!tb[TCA_FLOW_KEYS])
 			goto err2;

 		mode = FLOW_MODE_MAP;
 		if (tb[TCA_FLOW_MODE])
 			mode = nla_get_u32(tb[TCA_FLOW_MODE]);
 		if (mode != FLOW_MODE_HASH && nkeys > 1)
 			goto err2;

 		if (tb[TCA_FLOW_PERTURB]) {
 			if (mode != FLOW_MODE_HASH)
 				goto err2;
 			perturb_period = nla_get_u32(tb[TCA_FLOW_PERTURB]) * HZ;
 		}

 		if (TC_H_MAJ(baseclass) == 0) {
-			struct Qdisc *q = tcf_block_q(tp->chain->block);
+			struct tcf_block *block = tp->chain->block;
+			struct Qdisc *q;

+			if (tcf_block_shared(block)) {
+				NL_SET_ERR_MSG(extack,
+					       "Must specify baseclass when attaching flow filter to block");
+				goto err2;
+			}
+
+			q = tcf_block_q(block);
 			baseclass = TC_H_MAKE(q->handle, baseclass);
 		}
 		if (TC_H_MIN(baseclass) == 0)
 			baseclass = TC_H_MAKE(baseclass, 1);

 		fnew->handle = handle;
 		fnew->mask  = ~0U;
 		fnew->tp = tp;
 		get_random_bytes(&fnew->hashrnd, 4);
 	}

 	timer_setup(&fnew->perturb_timer, flow_perturbation, TIMER_DEFERRABLE);

 	tcf_block_netif_keep_dst(tp->chain->block);

 	if (tb[TCA_FLOW_KEYS]) {
 		fnew->keymask = keymask;
 		fnew->nkeys   = nkeys;
 	}

 	fnew->mode = mode;

 	if (tb[TCA_FLOW_MASK])
 		fnew->mask = nla_get_u32(tb[TCA_FLOW_MASK]);
 	if (tb[TCA_FLOW_XOR])
 		fnew->xor = nla_get_u32(tb[TCA_FLOW_XOR]);
 	if (tb[TCA_FLOW_RSHIFT])
 		fnew->rshift = nla_get_u32(tb[TCA_FLOW_RSHIFT]);
 	if (tb[TCA_FLOW_ADDEND])
 		fnew->addend = nla_get_u32(tb[TCA_FLOW_ADDEND]);

 	if (tb[TCA_FLOW_DIVISOR])
 		fnew->divisor = nla_get_u32(tb[TCA_FLOW_DIVISOR]);
 	if (baseclass)
 		fnew->baseclass = baseclass;

 	fnew->perturb_period = perturb_period;
 	if (perturb_period)
 		mod_timer(&fnew->perturb_timer, jiffies + perturb_period);

 	if (!*arg)
 		list_add_tail_rcu(&fnew->list, &head->filters);
 	else
 		list_replace_rcu(&fold->list, &fnew->list);

 	*arg = fnew;

 	if (fold) {
 		tcf_exts_get_net(&fold->exts);
 		tcf_queue_work(&fold->rwork, flow_destroy_filter_work);
 	}
 	return 0;

 err2:
 	tcf_exts_destroy(&fnew->exts);
 	tcf_em_tree_destroy(&fnew->ematches);
 err1:
 	kfree(fnew);
 	return err;
 }



